export function Feed({
  title = "{{title}}",
  state = "{{state}}",
  density = "{{density}}",
  accent = "{{accent}}",
  showTags = {{showTags}},
}) {
  const posts = [
    { title: "New export formats are live", tag: "Product", body: "Specimens can now be downloaded as HTML, Tailwind or React straight from the toolbar.", iso: "2026-08-18T08:00:00Z", when: "18 Aug, 8:00am" },
    { title: "Glossary search is faster", tag: "Performance", body: "Fuzzy search across every entry now returns results in under 50ms.", iso: "2026-08-16T13:20:00Z", when: "16 Aug, 1:20pm" },
    { title: "New contributor: Maya Singh", tag: "Community", body: "Maya joined the glossary team and shipped her first three entries this week.", iso: "2026-08-14T09:05:00Z", when: "14 Aug, 9:05am" },
  ];
  const wrap = { fontFamily: "system-ui, sans-serif", fontSize: 14, lineHeight: 1.5, color: "#241430", background: "#FAF7F2", border: "1.5px solid #24143022", borderRadius: 12, padding: 18, boxSizing: "border-box" };
  if (state === "loading") {
    return (
      <div style={wrap}>
        <h2 style={{ margin: "0 0 12px", fontSize: 16, fontWeight: 600 }}>{title}</h2>
        {[0, 1, 2].map((i) => (
          <div key={i} style={{ display: "flex", flexDirection: "column", gap: 6, padding: "6px 0 6px 12px", borderLeft: "3px solid #24143014", marginBottom: 12 }}>
            <span style={{ display: "block", height: 11, width: "55%", borderRadius: 4, background: "#24143020" }} />
            <span style={{ display: "block", height: 9, width: "90%", borderRadius: 4, background: "#24143016" }} />
            <span style={{ display: "block", height: 9, width: "35%", borderRadius: 4, background: "#24143016" }} />
          </div>
        ))}
      </div>
    );
  }
  if (state === "empty") {
    return (
      <div style={{ ...wrap, textAlign: "center", padding: "24px 18px" }}>
        <p style={{ margin: "8px 0 4px", fontWeight: 600 }}>Nothing here yet</p>
        <p style={{ margin: 0, fontSize: 13, color: "#241430aa" }}>New posts will appear here as they're published.</p>
      </div>
    );
  }
  const gap = density === "compact" ? 8 : 14;
  const compact = density === "compact";
  return (
    <div style={wrap}>
      <h2 style={{ margin: "0 0 12px", fontSize: 16, fontWeight: 600 }}>{title}</h2>
      <ul style={{ listStyle: "none", margin: 0, padding: 0, display: "flex", flexDirection: "column", gap }}>
        {posts.map((p) => (
          <li key={p.title} style={{ borderLeft: `3px solid ${accent}`, padding: compact ? "2px 0 2px 10px" : "4px 0 4px 12px" }}>
            <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
              <p style={{ margin: 0, fontWeight: 600, fontSize: 14 }}>{p.title}</p>
              {showTags && (
                <span style={{ fontSize: 10, fontWeight: 600, textTransform: "uppercase", background: "#24143012", padding: "2px 7px", borderRadius: 999 }}>{p.tag}</span>
              )}
            </div>
            {!compact && (
              <p style={{ margin: "4px 0", fontSize: 13, color: "#241430cc" }}>{p.body}</p>
            )}
            <time style={{ fontSize: 11, color: "#24143099" }} dateTime={p.iso}>{p.when}</time>
          </li>
        ))}
      </ul>
    </div>
  );
}
